#include <cstddef>
#include <vector>

// reserve: one allocation up front, capacity only. size() is unchanged
// and no element is constructed, so values[i] here would be UB.
std::vector<int> appended(std::size_t n) {
    std::vector<int> values;
    values.reserve(n);
    for (std::size_t i = 0; i < n; ++i) {
        values.push_back(static_cast<int>(i));
    }
    return values;
}

// resize: changes size() and constructs the elements, so subscripting
// below size() is valid immediately.
std::vector<int> sized(std::size_t n) {
    std::vector<int> values;
    values.resize(n);
    for (std::size_t i = 0; i < n; ++i) {
        values[i] = static_cast<int>(i);
    }
    return values;
}

#include <algorithm>
#include <vector>

struct Order {
    int id;
    bool filled;
};

// 1. Hand-written: erase returns the iterator to the next element.
// The naive version -- calling erase(it) inside a ++it loop -- is UB:
// erase invalidates it, and the loop then increments and compares it.
void remove_filled_loop(std::vector<Order>& orders) {
    for (auto it = orders.begin(); it != orders.end();) {
        if (it->filled) {
            it = orders.erase(it);
        } else {
            ++it;
        }
    }
}

// 2. Erase-remove: compact the survivors, then erase the tail.
void remove_filled_erase_remove(std::vector<Order>& orders) {
    orders.erase(
        std::remove_if(orders.begin(), orders.end(),
                       [](const Order& order) { return order.filled; }),
        orders.end());
}

// 3. C++20: the direct expression of the intent.
void remove_filled_erase_if(std::vector<Order>& orders) {
    std::erase_if(orders, [](const Order& order) { return order.filled; });
}

#include <array>

void clear_depths(std::array<int, 64>& depths) {
    depths.fill(0);  // no decay: the array knows its own length
}

static_assert(sizeof(std::array<int, 64>) == 64 * sizeof(int));

void prepare_depths() {
    // Default initialisation does NOT zero the scalar elements of a local
    // std::array; reading one before assigning it is undefined behaviour.
    //   std::array<int, 64> bad;

    std::array<int, 64> good{};  // value-initialised: all zero
    clear_depths(good);          // by reference: no 64-element copy
}

#include <cstddef>
#include <deque>
#include <optional>

struct Trade {
    int price;
    int quantity;
};

// push_back/pop_front are O(1) and never relocate existing elements:
// iterators are invalidated, but references and pointers to elements
// that are still present remain valid.
void record(std::deque<Trade>& window, Trade trade, std::size_t limit) {
    window.push_back(trade);
    if (window.size() > limit) {
        window.pop_front();
    }
}

std::optional<Trade> oldest(const std::deque<Trade>& window) {
    if (window.empty()) {
        return std::nullopt;  // front() on an empty deque is UB
    }
    return window.front();
}

// When `limit` is a known, modest bound, a reserved std::vector plus a
// head index is usually faster: contiguous scans, one allocation, and
// no page-map indirection on every access.

#include <queue>
#include <string>
#include <vector>

struct Event {
    long deadline_ns;
    std::string name;
};

// priority_queue is a max-heap under this comparison, so reversing it
// makes the earliest deadline compare as greatest and reach top().
struct EarlierDeadline {
    bool operator()(const Event& left, const Event& right) const {
        return left.deadline_ns > right.deadline_ns;
    }
};

using DeadlineQueue =
    std::priority_queue<Event, std::vector<Event>, EarlierDeadline>;

void dispatch(const Event&);

void run_due(DeadlineQueue& events, long now_ns) {
    // pop() returns void and destroys the element, so the event must be
    // taken from top() first. top() is a const T&, so this copies.
    while (!events.empty() && events.top().deadline_ns <= now_ns) {
        Event event = events.top();
        events.pop();
        dispatch(event);
    }
}

#include <array>
#include <list>
#include <queue>
#include <stack>
#include <vector>

struct Trade {
    int price;
    int quantity;
};

void choose(std::size_t expected_trades) {
    // Default: contiguous, cheapest scans, amortized growth. Reserve the
    // session's expected upper bound before the hot path.
    std::vector<Trade> history;
    history.reserve(expected_trades);

    // Size known at compile time: zero overhead, no allocation, no decay.
    std::array<int, 8> book_level{};

    // LIFO only: the adaptor makes the restricted discipline explicit.
    std::stack<int> undo;

    // FIFO only: hides every operation except the two ends.
    std::queue<int> inbox;

    // Stable handles across unrelated insertions and erasures, plus O(1)
    // splice between lists. Chosen for stability, not for "O(1) insert".
    std::list<Trade> pinned;
    std::list<Trade> settled;
    settled.splice(settled.begin(), pinned);

    (void)history; (void)book_level; (void)undo; (void)inbox;
}
